<div class="actions"><a class="button" href="<?= e(url('supplier-credits')) ?>"><?= e(t('← Supplier balances')) ?></a><?php if(can('settings.manage')): ?><a class="button" href="<?= e(url('suppliers/'.$supplier['id'].'/edit')) ?>"><?= e(t('Edit supplier')) ?></a><?php endif; ?></div>
<div class="credit-heading"><div><h2><?= e($supplier['name']) ?></h2><p class="muted"><?= e($supplier['phone']) ?> <?= e($supplier['address']) ?></p></div><span class="badge <?= (float)$balance>0?'production':'purchase' ?>"><?= (float)$balance>0?t('Outstanding credit'):t('Settled') ?></span></div>
<div class="metrics"><div class="metric"><span><?= e(t('Balance to pay')) ?></span><strong><?= e(money($balance)) ?> <small><?= e(t('MMK')) ?></small></strong><small><?= e(t('Current supplier credit')) ?></small></div><div class="metric"><span><?= e(t('Total purchases')) ?></span><strong><?= e(money(array_sum(array_column($purchases,'amount')))) ?> <small><?= e(t('MMK')) ?></small></strong></div><div class="metric"><span><?= e(t('Total paid')) ?></span><strong><?= e(money(array_sum(array_column($purchases,'amount_paid'))+array_sum(array_column($payments,'amount')))) ?> <small><?= e(t('MMK')) ?></small></strong><small><?= e(t('At purchase + later payments')) ?></small></div></div>
<section class="panel"><div class="panel-heading"><h2><?= e(t('Record supplier payment')) ?></h2><span class="muted"><?= e(t('Payments reduce this supplier\'s credit balance.')) ?></span></div><form method="post" action="<?= e(url('suppliers/'.$supplier['id'].'/payments')) ?>"><?= csrf_field() ?><input type="hidden" name="request_key" value="<?= e($requestKey) ?>"><div class="form-grid"><?php field('amount',t('Payment amount (MMK)'),'number','','required min="0.01" step="0.01" max="'.e($balance).'"');field('paid_on',t('Payment date'),'date',date('Y-m-d'),'required'); ?><label class="full"><?= e(t('Notes (optional)')) ?><textarea name="notes" maxlength="4000" rows="2"><?= e(old('notes')) ?></textarea></label></div><div class="form-footer"><span class="muted"><?= e(t('Current balance:')) ?> <?= e(money($balance)) ?> <?= e(t('MMK')) ?></span><button class="button primary" type="submit" <?= (float)$balance<=0?'disabled':'' ?>><?= e(t('Record payment')) ?></button></div></form></section>
<section class="panel"><div class="panel-heading"><h2><?= e(t('Purchase credit history')) ?></h2></div><div class="table-wrap"><table><thead><tr><th><?= e(t('Date / voucher')) ?></th><th><?= e(t('Warehouse')) ?></th><th class="number"><?= e(t('Purchase amount')) ?></th><th class="number"><?= e(t('Paid at purchase')) ?></th><th class="number"><?= e(t('Credit at purchase')) ?></th></tr></thead><tbody><?php foreach($purchases as $p): ?><tr><td><?= e($p['purchased_on']) ?><small><?php if(can('purchases.view')): ?><a href="<?= e(url('voucher/'.$p['id'])) ?>"><?= e($p['reference']) ?></a><?php else: ?><?= e($p['reference']) ?><?php endif; ?></small></td><td><?= e($p['warehouse']) ?></td><td class="number"><?= e(money($p['amount'])) ?></td><td class="number"><?= e(money($p['amount_paid'])) ?></td><td class="number"><?= e(money((float)$p['amount']-(float)$p['amount_paid'])) ?></td></tr><?php endforeach; ?><?php if(!$purchases): ?><tr><td colspan="5" class="empty"><?= e(t('No purchases from this supplier.')) ?></td></tr><?php endif; ?></tbody></table></div><div class="panel-foot"><?= e(t('Later payments settle the supplier balance as a whole; they are listed below.')) ?></div></section>
<section class="panel"><div class="panel-heading"><h2><?= e(t('Supplier payment history')) ?></h2></div><div class="table-wrap"><table><thead><tr><th><?= e(t('Date')) ?></th><th><?= e(t('Payment reference')) ?></th><th class="number"><?= e(t('Amount (MMK)')) ?></th><th><?= e(t('Recorded by')) ?></th><th><?= e(t('Notes')) ?></th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td><?= e($p['paid_on']) ?></td><td>PAY-<?= e($p['id']) ?></td><td class="number"><?= e(money($p['amount'])) ?></td><td><?= e($p['recorded_by']) ?></td><td class="notes-cell"><?= e($p['notes']?:'—') ?></td></tr><?php endforeach; ?><?php if(!$payments): ?><tr><td colspan="5" class="empty"><?= e(t('No later payments recorded.')) ?></td></tr><?php endif; ?></tbody></table></div></section>
